// Stencil doesn't watch json: on utilities.json change, touch the component's
// scss so the watch build re-runs the per-component Tailwind transform.
const fs = require('fs');
const path = require('path');

const componentsDir = path.resolve(__dirname, '../components');

const lastSeen = new Map();
fs.watch(componentsDir, { recursive: true }, (event, file) => {
  if (!file || !file.endsWith('utilities.json')) return;
  // macOS fires twice per save
  if (Date.now() - (lastSeen.get(file) || 0) < 200) return;
  lastSeen.set(file, Date.now());
  const dir = path.dirname(file);
  const scss = path.join(componentsDir, dir, `${path.basename(dir)}.scss`);
  if (!fs.existsSync(scss)) return console.log(`⚠️  [utilities] no scss for ${dir}, styles won't rebuild`);
  const now = new Date();
  fs.utimesSync(scss, now, now);
  console.log(`⚙️  [utilities] ${dir} changed, compiling new utilities...`);
});

console.log('👀 [utilities] watching src/components/**/utilities.json');
